// Phase-equilibrium / steam / relief catalogue wrapper (numbers in vle.gen.ts, generated by scripts/port-vle.py).
import type { Conf } from '../sim/types';
import { API_GEN, BFW_H_GEN, HENRY_GEN, NRTL_GEN, NRTL_R_GEN, STEAM_GEN } from './vle.gen';

export interface HenryRec { /** mol/(m3 Pa) at 298.15 K. */ Hcp: number; /** d ln H / d(1/T), K. */ C: number; src: string; conf: Conf }
export const HENRY: Readonly<Record<string, HenryRec>> = Object.fromEntries(
  Object.entries(HENRY_GEN).map(([k, v]) => [k, { ...v, src: 'Sander v5.0.0 via docs/research/vle_safety.md s3', conf: 'FETCHED' as Conf }])) as Record<string, HenryRec>;

/** Default K = y/x of gases without a catalogued Henry constant, or in a non-aqueous liquid (DESIGN 3.3, 4.5.1). */
export const K_HENRY_DEFAULT = 1e4;
/** Molar concentration of liquid water, mol/m3 (997 kg/m3 / 18.015 g/mol): converts Hcp to a mole-fraction Henry constant. GAME. */
export const C_WATER = 997 / 0.018015;

export interface SteamRec { P: number; T: number; hf: number; hg: number; hfg: number; src: string; conf: Conf }
export const STEAM_BAR: Readonly<Record<'LP' | 'MP' | 'HP', number>> = { LP: 4, MP: 10, HP: 40 };
/** Saturated steam at the three levels (SI: Pa, K, J/kg). */
export const STEAM: Readonly<Record<'LP' | 'MP' | 'HP', SteamRec>> = Object.fromEntries((['LP', 'MP', 'HP'] as const).map((k) => {
  const s = (STEAM_GEN as Record<string, { Tsat_C: number; hf: number; hg: number; hfg: number }>)[String(STEAM_BAR[k])]!;
  return [k, { P: STEAM_BAR[k] * 1e5, T: s.Tsat_C + 273.15, hf: s.hf * 1e3, hg: s.hg * 1e3, hfg: s.hfg * 1e3, src: 'IAPWS-IF97 via CoolProp, vle_safety.md s4', conf: 'F2' as Conf }];
})) as Record<'LP' | 'MP' | 'HP', SteamRec>;
/** Boiler feed water at 105 C, J/kg. */
export const BFW = { T: 105 + 273.15, h: BFW_H_GEN * 1e3, src: 'vle_safety.md s4', conf: 'F2' as Conf };

export const API = { C0: API_GEN.C0, Kd: API_GEN.Kd, src: 'API 520-1 via fluids.safety_valve (F2)', conf: 'F2' as Conf };
/** API 526 effective orifice areas by letter, mm2 (D..T). */
export const ORIFICE_MM2: Readonly<Record<string, number>> = Object.fromEntries(Object.entries(API_GEN.orifice).map(([k, v]) => [k, v.mm2]));
export const ORIFICE_LETTERS: readonly string[] = Object.keys(API_GEN.orifice);

/** NRTL binary pairs keyed 'A|B' (gas component ids, in the order the parameters were fitted): A in cal/mol, tau = A / (R T). */
export interface NrtlRec { A12: number; A21: number; alpha: number }
export const NRTL_PAIRS: Readonly<Record<string, NrtlRec & { src: string; conf: Conf }>> = Object.fromEntries(
  Object.entries(NRTL_GEN).map(([k, v]) => [k, { ...v, src: 'ChemSep/DECHEMA 1 atm via docs/research/vle_binary.py (DESIGN 4.5.1)', conf: 'F2' as Conf }])) as Record<string, NrtlRec & { src: string; conf: Conf }>;
export const NRTL_R: number = NRTL_R_GEN;
